WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_058089c7a8b41422>
    <urn:graphragprov:unit:u_9c472461b17dc197>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
